import type { MarketTrailArticle } from './types';

const minutesFromReadTime = (readTime: string) => {
  const value = Number.parseInt(readTime, 10);
  return Number.isFinite(value) ? value : 10;
};

const firstTag = (article: MarketTrailArticle, lang: 'pt' | 'en') => article.tags[lang][0] ?? 'Carreira';

const hasManualLayer = (article: MarketTrailArticle) =>
  article.sections.some((section) => section.title.pt === 'Como levar isso para a prática');

const careerTerms = [
  'carreira',
  'mercado',
  'vaga',
  'entrevista',
  'linkedin',
  'networking',
  'freelancer',
  'cliente',
  'salário',
  'liderança',
  'reputação',
  'promoção',
  'trabalho remoto',
  'autoridade',
  'burnout',
  'negócios',
];

const isCareerArticle = (article: MarketTrailArticle) => {
  const haystack = [
    article.title.pt,
    article.excerpt.pt,
    ...article.tags.pt,
    ...article.keywords.pt,
  ].join(' ').toLowerCase();

  return careerTerms.some((term) => haystack.includes(term));
};

const buildScenario = (article: MarketTrailArticle, tagPt: string, tagEn: string) => {
  const career = isCareerArticle(article);

  return {
    pt: career
      ? `Pense em uma pessoa que está tentando crescer na área. Ela estuda, entrega algumas coisas, acompanha profissionais mais experientes e sente que existe um espaço entre o que sabe hoje e o nível que o mercado espera dela. Esse espaço não se fecha com pressa. Ele se fecha com prática bem escolhida, leitura de ambiente, comunicação clara e decisões repetidas com mais critério.\n\nQuando o tema é ${tagPt}, o erro não costuma estar em não querer evoluir. Quase todo mundo quer. O problema aparece quando a pessoa tenta resolver tudo ao mesmo tempo, muda de direção a cada comparação e não registra o que aprendeu. Crescimento profissional precisa de memória. Se você não consegue olhar para os últimos três meses e explicar o que melhorou, provavelmente está confundindo movimento com evolução.`
      : `Imagine um projeto que começa pequeno. No início, tudo parece simples. Uma tela, uma rota, uma tabela, uma integração, uma regra de negócio. Só que software raramente permanece parado. O que hoje parece detalhe pode virar dependência de várias partes do sistema. Uma decisão tomada sem muito cuidado pode reaparecer meses depois como retrabalho, lentidão, bug difícil de explicar ou medo de alterar o próprio código.\n\nQuando o assunto envolve ${tagPt}, a diferença entre estudar e construir aparece com força. Estudar permite errar sem consequência. Construir exige pensar em manutenção, clareza, risco e gente usando aquilo depois. É por isso que um bom desenvolvedor não olha apenas para o código que funciona hoje. Ele tenta entender o que aquele código vai custar quando precisar mudar.`,
    en: career
      ? `Think of someone trying to grow in tech. They study, deliver a few things, follow more experienced people and feel the gap between what they know today and what the market expects. That gap does not close with hurry. It closes with well chosen practice, context reading, clear communication and repeated decisions made with better judgment.\n\nWhen the subject is ${tagEn}, the mistake is usually not lack of desire to improve. Most people want to improve. The problem appears when the person tries to solve everything at once, changes direction after every comparison and never records what they learned. Professional growth needs memory. If you cannot look at the last three months and explain what improved, you are probably confusing movement with evolution.`
      : `Imagine a project that starts small. At first, everything feels simple. One screen, one route, one table, one integration, one business rule. But software rarely stays still. What looks like a detail today can become a dependency for many parts of the system. A decision made without much care can return months later as rework, slowness, a bug that is hard to explain or fear of changing the code itself.\n\nWhen the subject involves ${tagEn}, the difference between studying and building becomes clear. Studying lets you make mistakes without consequence. Building requires thinking about maintenance, clarity, risk and people using the product later. That is why a good developer does not only look at code that works today. They try to understand what that code will cost when it needs to change.`,
  };
};

const buildManualSections = (article: MarketTrailArticle): MarketTrailArticle['sections'] => {
  const titlePt = article.title.pt;
  const titleEn = article.title.en;
  const tagPt = firstTag(article, 'pt').toLowerCase();
  const tagEn = firstTag(article, 'en').toLowerCase();
  const career = isCareerArticle(article);
  const scenario = buildScenario(article, tagPt, tagEn);
  const existingSectionPt = article.sections[0]?.title.pt ?? titlePt;
  const existingSectionEn = article.sections[0]?.title.en ?? titleEn;

  return [
    {
      title: { pt: 'Antes de tentar aplicar', en: 'Before trying to apply it' },
      content: {
        pt: `Este artigo precisa ser lido como parte de um manual, não como uma resposta rápida para consumir e esquecer. O ponto de ${titlePt} não é criar uma regra bonita. É ajudar você a perceber uma situação que provavelmente já apareceu no estudo, no trabalho, em um projeto próprio ou em alguma conversa profissional.\n\nMuita gente pula essa etapa porque quer chegar logo na prática. Eu entendo a vontade. Só que prática sem entendimento vira repetição. Você até faz alguma coisa, mas não sabe explicar por que fez. Quando muda o cenário, trava de novo. Por isso, antes de procurar ferramenta, template, biblioteca ou resposta pronta, tente entender qual problema este tema está tentando resolver.\n\nSe você está começando, leia procurando exemplos simples. Se já trabalha com desenvolvimento, leia procurando decisões que poderiam ter sido melhores em projetos reais. Se já tem experiência, leia procurando padrões que se repetem em equipes, produtos e clientes diferentes. O mesmo conteúdo pode ensinar coisas diferentes dependendo da fase em que você está.`,
        en: `This article should be read as part of a manual, not as a quick answer to consume and forget. The point of ${titleEn} is not to create a pretty rule. It is to help you notice a situation that has probably already appeared in study, work, a personal project or a professional conversation.\n\nMany people skip this step because they want to get straight to practice. I understand the urge. But practice without understanding becomes repetition. You do something, but you cannot explain why. When the scenario changes, you get stuck again. Before looking for a tool, template, library or ready answer, try to understand which problem this subject is trying to solve.\n\nIf you are starting out, read looking for simple examples. If you already work with development, read looking for decisions that could have been better in real projects. If you already have experience, read looking for patterns that repeat across teams, products and clients.`,
      },
    },
    {
      title: { pt: 'O cenário real por trás do assunto', en: 'The real scenario behind the subject' },
      content: scenario,
    },
    {
      title: { pt: 'O que costuma ficar escondido', en: 'What usually stays hidden' },
      content: {
        pt: `Todo assunto técnico ou profissional tem uma parte visível e uma parte escondida. A parte visível é o que aparece em vídeo curto, post, tutorial e conversa rápida. A parte escondida é o que surge quando você precisa sustentar a decisão no mundo real.\n\nEm ${titlePt}, a parte escondida costuma ser o custo da escolha. Uma escolha pode parecer boa porque resolve o problema de hoje, mas criar um problema maior amanhã. Outra pode parecer lenta no início, mas evitar meses de confusão. O desenvolvedor amadurece quando aprende a olhar para esse custo sem romantizar complexidade e sem cair na ilusão de que tudo precisa ser resolvido no improviso.\n\nO que quase ninguém fala é que muita decisão ruim não nasce de incompetência. Nasce de pressa, pressão, vaidade, medo de perguntar, falta de contexto ou excesso de confiança em uma resposta que funcionou em outro lugar. Quando você percebe isso, começa a julgar menos a pessoa e investigar mais o processo que levou à decisão.`,
        en: `Every technical or professional subject has a visible part and a hidden part. The visible part is what appears in short videos, posts, tutorials and quick conversations. The hidden part appears when you need to sustain the decision in the real world.\n\nIn ${titleEn}, the hidden part is usually the cost of the choice. A choice may look good because it solves today problem, but create a bigger problem tomorrow. Another may look slow at first, but avoid months of confusion. A developer matures when they learn to look at that cost without romanticizing complexity and without believing everything should be solved by improvisation.\n\nWhat almost nobody says is that many bad decisions are not born from incompetence. They come from hurry, pressure, vanity, fear of asking, lack of context or overconfidence in an answer that worked somewhere else. When you notice that, you start judging the person less and investigating more the process that led to the decision.`,
      },
    },
    {
      title: { pt: 'Como levar isso para a prática', en: 'How to put this into practice' },
      content: {
        pt: `A forma mais simples de usar este artigo não é tentar decorar tudo. É pegar a ideia central de ${titlePt} e transformar em uma decisão pequena no próximo projeto, estudo ou conversa técnica.\n\nQuando o assunto envolve ${tagPt}, muita gente entende o conceito enquanto lê, mas volta ao mesmo comportamento quando precisa agir. Por isso, a prática precisa ser visível. Anote o que você faria diferente hoje, escolha um exemplo real e teste essa mudança em algo pequeno. Pode ser um repositório pessoal, uma tarefa do trabalho, um texto no LinkedIn, uma conversa com outro desenvolvedor ou uma revisão de código.\n\nSe depois de aplicar você conseguir explicar o motivo da decisão sem depender de frase pronta, o artigo cumpriu o papel dele. Conhecimento técnico só vira maturidade quando muda a forma como você decide.`,
        en: `The simplest way to use this article is not to memorize everything. It is to take the central idea of ${titleEn} and turn it into a small decision in your next project, study session or technical conversation.\n\nWhen the subject involves ${tagEn}, many people understand the concept while reading, but return to the same behavior when they need to act. Practice needs to be visible. Write down what you would do differently today, choose a real example and test that change in something small.\n\nIf after applying it you can explain the decision without relying on a memorized phrase, the article did its job. Technical knowledge becomes maturity only when it changes the way you decide.`,
      },
    },
    {
      title: { pt: 'Um exemplo que vale testar', en: 'An example worth testing' },
      content: {
        pt: `Pegue um projeto que você já fez ou está construindo agora. Abra o código, a documentação, o histórico de commits ou o planejamento e procure um ponto onde a ideia deste artigo apareça. Não precisa ser um projeto grande. Projetos pequenos mostram problemas com mais clareza porque não existe tanta coisa escondendo a decisão principal.\n\nFaça três perguntas. O que eu fiz apenas porque era o jeito mais rápido. O que eu fiz porque realmente entendi o problema. O que uma pessoa nova no projeto entenderia sem me perguntar nada.\n\nEssas três perguntas costumam revelar mais do que uma lista enorme de ferramentas. Elas mostram se você está acumulando tecnologia ou desenvolvendo julgamento profissional.`,
        en: `Take a project you already built or are building now. Open the code, documentation, commit history or plan and look for one place where the idea of this article appears. It does not need to be a large project. Small projects show problems more clearly because there is less noise hiding the main decision.\n\nAsk three questions. What did I do only because it was faster. What did I do because I truly understood the problem. What would a new person understand without asking me anything.\n\nThese questions reveal more than a long list of tools. They show whether you are collecting technology or developing professional judgment.`,
      },
    },
    {
      title: { pt: 'Um caso comum que eu observaria', en: 'A common case I would observe' },
      content: {
        pt: career
          ? `Um caso muito comum é a pessoa achar que precisa provar valor o tempo inteiro. Ela aceita demanda demais, responde rápido demais, muda de prioridade sem critério e tenta mostrar que dá conta de tudo. No começo isso pode parecer dedicação. Com o tempo, começa a virar ruído. A pessoa perde profundidade, erra mais, comunica pior e deixa de construir uma direção clara.\n\nSe eu estivesse analisando esse caso, não começaria perguntando se a pessoa está se esforçando. O esforço já existe. Eu perguntaria onde esse esforço está indo. Está indo para construir base. Está indo para entregar melhor. Está indo para criar reputação. Está indo para aprender com problemas reais. Ou está indo apenas para parecer ocupado.\n\nEssa diferença muda muita coisa. O mercado não premia apenas quem está cansado. Ele tende a confiar mais em quem consegue transformar energia em entrega, entrega em aprendizado e aprendizado em decisão melhor no próximo ciclo.`
          : `Um caso comum é o projeto funcionar bem no primeiro mês e começar a ficar confuso no terceiro. Ninguém percebe de uma vez. Primeiro aparece uma regra duplicada. Depois um nome que já não representa o que a função faz. Depois uma integração que só uma pessoa entende. Depois um bug que parece simples, mas exige abrir metade do projeto para descobrir a causa.\n\nSe eu estivesse analisando esse caso, não começaria procurando culpado. Eu procuraria o ponto onde o projeto deixou de explicar a si mesmo. Pode ter sido falta de separação de responsabilidade, falta de teste, ausência de documentação, modelagem fraca, decisão apressada ou uma abstração criada antes da hora.\n\nO importante é entender que software fica caro quando perde legibilidade. Código confuso cobra juros. Quanto mais tempo passa, mais difícil fica pagar essa dívida sem parar tudo. Por isso, pensar bem agora quase sempre é mais barato do que corrigir no susto depois.`,
        en: career
          ? `A very common case is someone believing they need to prove value all the time. They accept too many demands, answer too fast, change priorities without judgment and try to show they can handle everything. At first this may look like dedication. With time, it becomes noise. The person loses depth, makes more mistakes, communicates worse and stops building a clear direction.\n\nIf I were analyzing this case, I would not start by asking if the person is making effort. The effort already exists. I would ask where that effort is going. Is it building fundamentals. Is it improving delivery. Is it creating reputation. Is it learning from real problems. Or is it only trying to look busy.\n\nThat difference changes a lot. The market does not reward only who is tired. It tends to trust people who can turn energy into delivery, delivery into learning and learning into better decisions in the next cycle.`
          : `A common case is a project working well in the first month and becoming confusing by the third. Nobody notices at once. First comes a duplicated rule. Then a name that no longer represents what a function does. Then an integration that only one person understands. Then a bug that looks simple, but requires opening half of the project to discover the cause.\n\nIf I were analyzing this case, I would not start by looking for blame. I would look for the point where the project stopped explaining itself. It may have been lack of responsibility separation, lack of tests, missing documentation, weak modeling, a rushed decision or an abstraction created too early.\n\nThe important thing is understanding that software gets expensive when it loses readability. Confusing code charges interest. The more time passes, the harder it becomes to pay that debt without stopping everything. Thinking well now is almost always cheaper than fixing in panic later.`,
      },
    },
    {
      title: { pt: 'Erros que aparecem no mercado', en: 'Mistakes that appear in the market' },
      content: {
        pt: `O erro mais comum é tratar esse tema como algo isolado. A pessoa lê, concorda e segue para o próximo conteúdo, mas não conecta a ideia com o modo como trabalha. No mercado, isso aparece em pequenas falhas repetidas. Uma tarefa mal entendida, uma decisão que ninguém documentou, um prazo aceito sem critério, um código difícil de revisar, uma conversa técnica que poderia ter sido mais clara.\n\nOutro erro é procurar uma regra universal. Desenvolvimento de software quase nunca funciona assim. A resposta certa depende do contexto, do risco, do momento do produto, da equipe e da consequência da decisão. O que diferencia um profissional melhor não é ter uma opinião forte sobre tudo. É saber explicar por que aquela escolha faz sentido naquele cenário.`,
        en: `The most common mistake is treating this subject as isolated. The person reads, agrees and moves to the next piece of content, but never connects the idea with the way they work. In the market, this appears as repeated small failures. A poorly understood task, an undocumented decision, a deadline accepted without judgment, code that is hard to review, a technical conversation that could have been clearer.\n\nAnother mistake is looking for a universal rule. Software development rarely works that way. The right answer depends on context, risk, product stage, team and consequence. What separates a better professional is not having a strong opinion about everything. It is knowing why a choice makes sense in that specific scenario.`,
      },
    },
    {
      title: { pt: 'Como investigar sem se perder', en: 'How to investigate without getting lost' },
      content: {
        pt: `Quando você não sabe por onde começar, reduza o problema. Em vez de perguntar como dominar ${tagPt}, pergunte onde esse assunto apareceu pela última vez na sua rotina. Foi em uma tarefa. Foi em um projeto pessoal. Foi em uma conversa de entrevista. Foi em uma decisão que você aceitou sem entender. Foi em um bug. Foi em um cliente pedindo algo que parecia simples.\n\nDepois disso, separe observação de conclusão. Observação é o que aconteceu. Conclusão é o que você acha que aquilo significa. Muita gente pula direto para a conclusão e erra o diagnóstico. Antes de decidir que precisa aprender uma nova ferramenta, veja se o problema não era falta de base. Antes de decidir que precisa refatorar tudo, veja se não era apenas uma responsabilidade fora do lugar. Antes de decidir que a equipe não valoriza seu trabalho, veja se você está comunicando impacto com clareza.\n\nEssa separação parece pequena, mas muda a qualidade da decisão. Desenvolvedor bom não é quem nunca se perde. É quem cria método para voltar ao problema central quando o cenário fica confuso.`,
        en: `When you do not know where to start, reduce the problem. Instead of asking how to master ${tagEn}, ask where this subject last appeared in your routine. Was it in a task. Was it in a personal project. Was it in an interview conversation. Was it in a decision you accepted without understanding. Was it in a bug. Was it in a client asking for something that looked simple.\n\nThen separate observation from conclusion. Observation is what happened. Conclusion is what you think it means. Many people jump straight to conclusion and misread the problem. Before deciding you need to learn a new tool, check if the problem was not lack of fundamentals. Before deciding you need to refactor everything, check if it was only a misplaced responsibility. Before deciding the team does not value your work, check if you are communicating impact clearly.\n\nThat separation looks small, but it changes the quality of the decision. A good developer is not someone who never gets lost. It is someone who creates method to return to the central problem when the scenario gets confusing.`,
      },
    },
    {
      title: { pt: 'Como isso muda conforme você evolui', en: 'How this changes as you grow' },
      content: {
        pt: `No começo, você provavelmente vai enxergar ${titlePt} como uma técnica ou uma dica. É normal. Quem está começando precisa de pontos concretos para segurar. O problema é parar aí. Com o tempo, esse assunto precisa deixar de ser uma dica solta e virar critério.\n\nPara um iniciante, o objetivo é reconhecer o problema quando ele aparece. Para um júnior, é aplicar com orientação e registrar o aprendizado. Para um pleno, é decidir com mais autonomia e explicar o tradeoff. Para um sênior, é ajudar outras pessoas a não repetirem o mesmo erro. Para alguém que lidera projeto, é transformar a ideia em processo leve, documentação útil ou decisão compartilhada.\n\nEssa progressão mostra uma coisa importante. O mesmo assunto não acaba quando você entende a definição. Ele volta em camadas. Você aprende uma vez no estudo, outra vez no trabalho, outra vez quando precisa ensinar, outra vez quando precisa assumir responsabilidade por uma decisão que afeta outras pessoas.`,
        en: `At the beginning, you will probably see ${titleEn} as a technique or a tip. That is normal. Beginners need concrete points to hold onto. The problem is stopping there. With time, this subject needs to stop being a loose tip and become judgment.\n\nFor a beginner, the goal is recognizing the problem when it appears. For a junior, it is applying it with guidance and recording the learning. For a mid-level developer, it is deciding with more autonomy and explaining the tradeoff. For a senior, it is helping other people avoid the same mistake. For someone leading a project, it is turning the idea into a light process, useful documentation or shared decision.\n\nThat progression shows something important. The same subject does not end when you understand the definition. It returns in layers. You learn it once in study, again at work, again when you need to teach, again when you need to take responsibility for a decision that affects other people.`,
      },
    },
    {
      title: { pt: 'O que observar em um projeto real', en: 'What to observe in a real project' },
      content: {
        pt: `Abra um projeto e procure sinais. Não procure perfeição. Projeto real sempre tem partes boas, partes medianas e partes que nasceram sob pressão. O objetivo é observar com honestidade.\n\nVeja se as decisões principais estão visíveis. Veja se uma pessoa nova conseguiria entender o fluxo principal. Veja se os nomes ajudam ou atrapalham. Veja se existe documentação mínima para continuar o trabalho. Veja se os erros são tratados com clareza. Veja se uma mudança pequena exigiria coragem demais. Veja se a regra de negócio está em um lugar coerente. Veja se o histórico do projeto conta uma história ou parece um conjunto de remendos sem direção.\n\nDepois conecte essa observação com ${titlePt}. Em que ponto esse artigo aparece ali. O que ele explica. O que ele não resolve. O que você mudaria hoje se tivesse tempo e responsabilidade sobre esse projeto. Esse exercício transforma leitura em análise técnica de verdade.`,
        en: `Open a project and look for signals. Do not look for perfection. Real projects always have good parts, average parts and parts created under pressure. The goal is to observe honestly.\n\nCheck if the main decisions are visible. Check if a new person could understand the main flow. Check if names help or hurt. Check if there is minimal documentation to continue the work. Check if errors are handled clearly. Check if a small change would require too much courage. Check if the business rule lives in a coherent place. Check if the project history tells a story or feels like a set of patches without direction.\n\nThen connect that observation with ${titleEn}. Where does this article appear there. What does it explain. What does it not solve. What would you change today if you had time and responsibility over that project. This exercise turns reading into real technical analysis.`,
      },
    },
    {
      title: { pt: 'Checklist antes de seguir', en: 'Checklist before moving on' },
      content: {
        pt: `Antes de ir para o próximo artigo, faça uma checagem honesta.\n\nVocê consegue explicar esse assunto com suas próprias palavras. Você consegue mostrar um exemplo real. Você sabe onde esse tema aparece em um projeto de verdade. Você entende o erro mais comum. Você sabe qual pequena mudança pode aplicar esta semana. Você consegue conectar este conteúdo com outro ponto da sua carreira.\n\nSe a resposta for não para quase tudo, não tem problema. Volte um passo. Releia com calma. A pressa para terminar a trilha não pode ser maior do que a intenção de sair dela mais preparado.`,
        en: `Before moving to the next article, do an honest check.\n\nCan you explain this subject in your own words. Can you show a real example. Do you know where it appears in a real project. Do you understand the most common mistake. Do you know one small change you can apply this week. Can you connect this content with another part of your career.\n\nIf the answer is no to almost everything, that is fine. Take one step back. Read it again calmly. The rush to finish the trail cannot be bigger than the intention to leave it better prepared.`,
      },
    },
    {
      title: { pt: 'Perguntas que eu faria antes de decidir', en: 'Questions I would ask before deciding' },
      content: {
        pt: `Qual problema estou tentando resolver de verdade. Quem sente esse problema. O que acontece se eu não resolver agora. O que acontece se eu resolver do jeito mais rápido. O que acontece se eu resolver do jeito mais robusto. Qual parte eu entendo bem. Qual parte estou fingindo que entendo. Que informação falta. Quem pode ser afetado pela decisão. Como vou explicar isso depois.\n\nEssas perguntas parecem simples, mas reduzem muito erro. Elas tiram a decisão do campo da sensação e colocam no campo da responsabilidade. Às vezes a resposta mostra que você precisa estudar mais. Às vezes mostra que precisa perguntar para alguém. Às vezes mostra que precisa cortar escopo. Às vezes mostra que a solução técnica nem era o ponto principal.\n\nO desenvolvedor que aprende a perguntar melhor começa a errar melhor também. E errar melhor não é pouca coisa. Significa errar de um jeito que gera aprendizado, não dívida escondida.`,
        en: `Which problem am I really trying to solve. Who feels this problem. What happens if I do not solve it now. What happens if I solve it in the fastest way. What happens if I solve it in the most robust way. Which part do I understand well. Which part am I pretending to understand. What information is missing. Who may be affected by the decision. How will I explain this later.\n\nThese questions look simple, but they reduce many mistakes. They take the decision out of pure feeling and place it inside responsibility. Sometimes the answer shows you need to study more. Sometimes it shows you need to ask someone. Sometimes it shows you need to cut scope. Sometimes it shows the technical solution was not the main point.\n\nThe developer who learns to ask better also starts making better mistakes. And better mistakes matter. It means making mistakes that generate learning, not hidden debt.`,
      },
    },
    {
      title: { pt: 'Exercício de evolução', en: 'Growth exercise' },
      content: {
        pt: `Escolha uma situação real e escreva uma explicação curta sobre ela. Pode ser uma decisão técnica, uma dúvida de estudo, um problema de arquitetura, um trecho de código, uma conversa com cliente ou uma dificuldade de carreira. O objetivo é transformar pensamento solto em clareza.\n\nDepois disso, revise o texto como se fosse enviar para alguém da equipe. Corte o que estiver confuso. Troque generalizações por exemplos. Explique o motivo da decisão. Esse exercício parece simples, mas treina uma habilidade que acompanha toda a carreira. Desenvolvedor que pensa bem e comunica bem costuma resolver problemas antes que eles virem ruído.`,
        en: `Choose a real situation and write a short explanation about it. It can be a technical decision, a study doubt, an architecture problem, a piece of code, a client conversation or a career difficulty. The goal is to turn loose thinking into clarity.\n\nThen review the text as if you were sending it to someone on the team. Cut what is confusing. Replace generalizations with examples. Explain the reason behind the decision. This exercise seems simple, but it trains a skill that follows the entire career. A developer who thinks clearly and communicates clearly usually solves problems before they become noise.`,
      },
    },
    {
      title: { pt: 'Exercício maior para virar referência', en: 'A bigger exercise to become a reference' },
      content: {
        pt: `Se você quiser levar este artigo a sério, não pare no exercício pequeno. Transforme o tema em um estudo público ou em uma documentação interna. Escreva um texto explicando o problema, o cenário, duas decisões possíveis, o risco de cada uma e o caminho que você escolheria. Não precisa publicar se não quiser. O importante é construir clareza suficiente para que outra pessoa consiga acompanhar seu raciocínio.\n\nDepois, adicione um exemplo concreto. Pode ser um trecho de código, um desenho de fluxo, uma tabela comparando alternativas, uma explicação de arquitetura, uma revisão de README, uma simulação de conversa com cliente ou uma análise de carreira. O formato depende do tema. O objetivo é sair da opinião solta e chegar em evidência.\n\nEsse tipo de prática cria repertório. Repertório é o que faz você responder melhor em entrevistas, revisar código com mais critério, conversar com líderes com mais segurança e perceber problemas antes que eles fiquem caros. Quem documenta o próprio aprendizado constrói uma vantagem silenciosa.`,
        en: `If you want to take this article seriously, do not stop at the small exercise. Turn the subject into a public study or internal documentation. Write a text explaining the problem, the scenario, two possible decisions, the risk of each one and the path you would choose. You do not need to publish it if you do not want to. The important part is building enough clarity for another person to follow your reasoning.\n\nThen add a concrete example. It can be a code snippet, a flow drawing, a table comparing alternatives, an architecture explanation, a README review, a simulated client conversation or a career analysis. The format depends on the subject. The goal is to move from loose opinion to evidence.\n\nThis kind of practice creates repertoire. Repertoire is what helps you answer better in interviews, review code with more judgment, talk to leaders with more confidence and notice problems before they become expensive. People who document their own learning build a quiet advantage.`,
      },
    },
    {
      title: { pt: 'Sinais de que você entendeu de verdade', en: 'Signs that you truly understood it' },
      content: {
        pt: `Você entendeu de verdade quando consegue simplificar sem empobrecer. Quando consegue explicar para alguém iniciante sem transformar o assunto em palestra confusa. Quando consegue discordar de uma solução com respeito e mostrar o risco. Quando consegue admitir que uma resposta depende do contexto. Quando consegue aplicar a ideia em um projeto diferente daquele em que aprendeu.\n\nOutro sinal importante é perceber limite. Entender ${titlePt} não significa resolver qualquer situação ligada a ${tagPt}. Significa ter mais critério para investigar, testar e decidir. Profissional maduro não promete domínio absoluto. Ele demonstra método. E método costuma valer mais do que confiança performática.\n\nSe você ainda não chegou nesse ponto, não precisa se desesperar. A trilha existe justamente para isso. Cada artigo adiciona uma camada. Algumas camadas só fazem sentido depois de prática. Outras fazem sentido na hora, mas só ficam profundas meses depois, quando você encontra o problema real.`,
        en: `You truly understood it when you can simplify without making it shallow. When you can explain it to a beginner without turning the subject into a confusing lecture. When you can disagree with a solution respectfully and show the risk. When you can admit an answer depends on context. When you can apply the idea in a different project from the one where you learned it.\n\nAnother important sign is noticing limits. Understanding ${titleEn} does not mean solving every situation related to ${tagEn}. It means having better judgment to investigate, test and decide. A mature professional does not promise absolute mastery. They demonstrate method. And method is usually worth more than performative confidence.\n\nIf you are not there yet, do not panic. The trail exists exactly for that. Each article adds a layer. Some layers only make sense after practice. Others make sense immediately, but become deeper months later when you meet the real problem.`,
      },
    },
    {
      title: { pt: 'Perguntas frequentes sem enrolação', en: 'Common questions without noise' },
      content: {
        pt: `Preciso dominar isso antes de continuar. Não. Você precisa entender o suficiente para reconhecer o problema e praticar com alguma intenção. Domínio vem com repetição, projeto real e revisão do próprio erro.\n\nIsso serve para iniciante. Sim, mas não do mesmo jeito que serve para alguém experiente. O iniciante usa para construir base. O profissional usa para tomar decisão melhor. A diferença está no nível de consequência.\n\nDá para aprender só lendo. Não. Leitura orienta, encurta caminho e organiza pensamento, mas não substitui prática. Se você lê e não aplica em nada, o conteúdo vira sensação de progresso.\n\nComo saber se estou evoluindo. Veja se suas explicações estão mais claras, se seus projetos estão mais legíveis, se suas decisões têm menos chute e se você consegue identificar erros antigos com mais precisão.`,
        en: `Do I need to master this before moving on. No. You need to understand enough to recognize the problem and practice with intention. Mastery comes with repetition, real projects and reviewing your own mistakes.\n\nDoes this help beginners. Yes, but not in the same way it helps experienced people. The beginner uses it to build fundamentals. The professional uses it to make better decisions. The difference is the level of consequence.\n\nCan I learn only by reading. No. Reading guides, shortens the path and organizes thinking, but it does not replace practice. If you read and apply nothing, content becomes a feeling of progress.\n\nHow do I know I am improving. See if your explanations are clearer, if your projects are more readable, if your decisions have less guessing and if you can identify old mistakes with more precision.`,
      },
    },
    {
      title: { pt: 'Roteiro de estudo para uma semana', en: 'A study plan for one week' },
      content: {
        pt: `No primeiro dia, leia o artigo inteiro sem tentar transformar tudo em tarefa. O objetivo é entender a ideia geral. Marque apenas os trechos que incomodaram ou fizeram você lembrar de alguma situação real. Normalmente esses trechos mostram onde existe uma lacuna.\n\nNo segundo dia, escolha um projeto pequeno e procure sinais do tema. Se o artigo fala de decisão técnica, procure uma decisão mal explicada. Se fala de carreira, procure uma situação em que você não soube se posicionar. Se fala de ${tagPt}, procure onde esse assunto aparece de forma concreta, não apenas como teoria.\n\nNo terceiro dia, escreva uma explicação curta. Não publique ainda. Explique o problema como se estivesse conversando com uma pessoa menos experiente. Se você não consegue explicar sem esconder atrás de termos bonitos, provavelmente ainda não entendeu o suficiente.\n\nNo quarto dia, compare duas alternativas. Uma mais rápida e uma mais cuidadosa. Escreva o custo das duas. O que cada uma resolve. O que cada uma deixa pendente. O que pode quebrar depois. Esse exercício treina tomada de decisão, que é uma das habilidades mais importantes em desenvolvimento de software.\n\nNo quinto dia, aplique uma pequena melhoria. Pode ser renomear algo, escrever um README melhor, criar um teste, revisar uma rota, melhorar uma consulta, organizar um fluxo, ajustar seu currículo, reescrever uma descrição de projeto ou registrar uma decisão profissional.\n\nNo sexto dia, peça leitura externa se fizer sentido. Pode ser um colega, mentor, amigo desenvolvedor ou alguém da equipe. Não peça apenas aprovação. Peça para a pessoa apontar o que ficou confuso.\n\nNo sétimo dia, registre o aprendizado. O que você entendia antes. O que entende agora. O que ainda não consegue explicar. Esse registro vira histórico. Sem histórico, você depende de memória e sensação. Com histórico, você enxerga evolução.`,
        en: `On the first day, read the whole article without trying to turn everything into a task. The goal is to understand the general idea. Mark only the parts that bothered you or reminded you of a real situation. Those parts usually show where there is a gap.\n\nOn the second day, choose a small project and look for signals of the subject. If the article talks about technical decision, look for a poorly explained decision. If it talks about career, look for a situation where you did not know how to position yourself. If it talks about ${tagEn}, look for where that subject appears concretely, not only as theory.\n\nOn the third day, write a short explanation. Do not publish it yet. Explain the problem as if you were talking to a less experienced person. If you cannot explain without hiding behind pretty terms, you probably still do not understand enough.\n\nOn the fourth day, compare two alternatives. One faster and one more careful. Write the cost of both. What each one solves. What each one leaves open. What may break later. This exercise trains decision making, one of the most important skills in software development.\n\nOn the fifth day, apply a small improvement. It can be renaming something, writing a better README, creating a test, reviewing a route, improving a query, organizing a flow, adjusting your resume, rewriting a project description or recording a professional decision.\n\nOn the sixth day, ask for an external reading if it makes sense. It can be a colleague, mentor, developer friend or someone from the team. Do not ask only for approval. Ask the person to point out what is confusing.\n\nOn the seventh day, register the learning. What you understood before. What you understand now. What you still cannot explain. This record becomes history. Without history, you depend on memory and feeling. With history, you see evolution.`,
      },
    },
    {
      title: { pt: 'Quando isso vira portfólio ou reputação', en: 'When this becomes portfolio or reputation' },
      content: {
        pt: `Um assunto começa a virar portfólio quando deixa de ser apenas algo que você consumiu e passa a ser algo que você consegue demonstrar. Não precisa ser um projeto enorme. Às vezes um README bem escrito, um pequeno estudo técnico, uma comparação entre soluções ou uma melhoria documentada já mostra mais maturidade do que uma aplicação cheia de telas sem explicação.\n\nNo caso de ${titlePt}, pense em como transformar aprendizado em evidência. Se for um tema técnico, crie um exemplo simples, explique a decisão e mostre o limite da abordagem. Se for um tema de carreira, escreva um relato honesto sobre o que você mudaria na própria rotina. Se for um tema de mercado, mostre como aquela ideia afeta entrega, comunicação, custo ou confiança.\n\nReputação não nasce de autopromoção vazia. Nasce da repetição de sinais confiáveis. A pessoa lê algo seu e percebe clareza. Vê um projeto seu e percebe cuidado. Conversa com você e percebe responsabilidade. Esse conjunto vale muito mais do que tentar parecer especialista em tudo.\n\nUma boa forma de medir isso é perguntar se alguém conseguiria confiar um problema pequeno a você depois de ler sua explicação. Se a resposta for sim, você construiu reputação em miniatura. Se a resposta for não, talvez falte exemplo, contexto ou honestidade sobre os limites da solução.`,
        en: `A subject starts becoming portfolio when it stops being only something you consumed and becomes something you can demonstrate. It does not need to be a huge project. Sometimes a well written README, a small technical study, a comparison between solutions or a documented improvement already shows more maturity than an application full of screens without explanation.\n\nFor ${titleEn}, think about turning learning into evidence. If it is a technical subject, create a simple example, explain the decision and show the limit of the approach. If it is a career subject, write an honest report about what you would change in your own routine. If it is a market subject, show how that idea affects delivery, communication, cost or trust.\n\nReputation is not born from empty self-promotion. It is born from repeated reliable signals. Someone reads something from you and notices clarity. Sees a project from you and notices care. Talks to you and notices responsibility. That set is worth much more than trying to look like an expert in everything.\n\nA good way to measure this is asking whether someone could trust you with a small problem after reading your explanation. If the answer is yes, you built reputation in miniature. If the answer is no, maybe the explanation lacks example, context or honesty about the limits of the solution.`,
      },
    },
    {
      title: { pt: 'Comparações que evitam confusão', en: 'Comparisons that avoid confusion' },
      content: {
        pt: `Existem comparações que ajudam a pensar. Velocidade não é a mesma coisa que pressa. Simplicidade não é ausência de critério. Organização não é burocracia. Autonomia não é fazer tudo sozinho. Experiência não é decorar respostas. Senioridade não é falar difícil. Arquitetura não é desenhar caixas bonitas. Produto não é só interface. Carreira não é apenas mudar de cargo.\n\nEssas diferenças parecem óbvias quando escritas, mas somem facilmente no dia a dia. Uma equipe chama pressa de agilidade. Um desenvolvedor chama improviso de pragmatismo. Uma empresa chama falta de processo de liberdade. Um freelancer chama falta de escopo de flexibilidade. Um iniciante chama coleção de cursos de evolução.\n\nQuando você estudar ${titlePt}, tente encontrar essas confusões. Elas revelam onde o vocabulário está escondendo o problema real. Se duas pessoas usam a mesma palavra com sentidos diferentes, a conversa já começa torta. Parte do trabalho profissional é alinhar significado antes de alinhar solução.\n\nUma técnica simples é pedir exemplo. Quando alguém diz que precisa de algo escalável, pergunte escalável em quê. Usuários. Dados. Equipe. Código. Infraestrutura. Processo. Quando alguém diz que algo está complexo, pergunte onde a complexidade dói. Leitura. Alteração. Deploy. Custo. Treinamento. Suporte. A palavra geral quase sempre precisa virar situação concreta.`,
        en: `Some comparisons help thinking. Speed is not the same as hurry. Simplicity is not lack of judgment. Organization is not bureaucracy. Autonomy is not doing everything alone. Experience is not memorizing answers. Seniority is not speaking in a difficult way. Architecture is not drawing pretty boxes. Product is not only interface. Career is not only changing titles.\n\nThese differences look obvious when written, but disappear easily in daily work. A team calls hurry agility. A developer calls improvisation pragmatism. A company calls lack of process freedom. A freelancer calls lack of scope flexibility. A beginner calls a collection of courses evolution.\n\nWhen studying ${titleEn}, try to find these confusions. They reveal where vocabulary is hiding the real problem. If two people use the same word with different meanings, the conversation already starts crooked. Part of professional work is aligning meaning before aligning solution.\n\nA simple technique is asking for an example. When someone says they need something scalable, ask scalable in what. Users. Data. Team. Code. Infrastructure. Process. When someone says something is complex, ask where the complexity hurts. Reading. Changing. Deploy. Cost. Training. Support. A general word almost always needs to become a concrete situation.`,
      },
    },
    {
      title: { pt: 'Como eu revisaria esse aprendizado', en: 'How I would review this learning' },
      content: {
        pt: `Eu não revisaria perguntando se você gostou do artigo. Gostar não prova aprendizado. Eu olharia para três coisas. Sua explicação, sua aplicação e sua mudança de comportamento.\n\nNa explicação, eu observaria se você consegue falar sobre o assunto sem repetir o texto. Se você depende exatamente das mesmas palavras, talvez ainda esteja reproduzindo. Quando entende, você consegue trocar a ordem, usar outro exemplo e ainda preservar a ideia.\n\nNa aplicação, eu observaria se existe algum resultado visível. Pode ser pequeno. Um commit melhor explicado. Uma issue mais clara. Uma conversa mais objetiva. Uma decisão registrada. Um código menos confuso. Uma pergunta melhor em uma reunião. Um projeto de portfólio com intenção mais clara.\n\nNa mudança de comportamento, eu observaria se você evita o erro antigo. O sinal mais forte de aprendizado não é falar bonito sobre o assunto. É tomar uma decisão diferente quando a situação aparece novamente. Se antes você aceitava qualquer prazo e agora pergunta escopo, houve aprendizado. Se antes copiava arquitetura sem entender e agora questiona contexto, houve aprendizado. Se antes acumulava conteúdo e agora aplica uma parte com consistência, houve aprendizado.\n\nEssa revisão é exigente, mas justa. Ela não pede perfeição. Pede evidência.`,
        en: `I would not review by asking if you liked the article. Liking it does not prove learning. I would look at three things. Your explanation, your application and your behavior change.\n\nIn the explanation, I would observe whether you can talk about the subject without repeating the text. If you depend on the exact same words, maybe you are still reproducing. When you understand, you can change the order, use another example and still preserve the idea.\n\nIn the application, I would observe whether there is any visible result. It can be small. A better explained commit. A clearer issue. A more objective conversation. A recorded decision. Less confusing code. A better question in a meeting. A portfolio project with clearer intention.\n\nIn the behavior change, I would observe whether you avoid the old mistake. The strongest sign of learning is not speaking beautifully about the subject. It is making a different decision when the situation appears again. If before you accepted any deadline and now ask about scope, there was learning. If before you copied architecture without understanding and now question context, there was learning. If before you accumulated content and now apply one part consistently, there was learning.\n\nThis review is demanding, but fair. It does not ask for perfection. It asks for evidence.`,
      },
    },
    {
      title: { pt: 'Perguntas para reler depois', en: 'Questions to revisit later' },
      content: {
        pt: `O que mudou na minha forma de pensar depois deste artigo. Onde esse assunto aparece no meu projeto atual. Que decisão eu tenho evitado por falta de clareza. Que parte eu entendi na teoria, mas ainda não provei na prática. Quem poderia se beneficiar se eu explicasse isso de forma simples.\n\nEssas perguntas ajudam a transformar a trilha em manual de consulta, não apenas em sequência de leitura. Em fases diferentes da carreira, o mesmo artigo pode bater de outro jeito. O iniciante enxerga uma camada. O júnior enxerga outra. O pleno percebe outra. O sênior volta e percebe que o básico bem feito ainda sustenta tudo.`,
        en: `What changed in my thinking after this article. Where does this subject appear in my current project. What decision have I been avoiding because I lack clarity. What did I understand in theory but have not proven in practice yet. Who could benefit if I explained this in simple language.\n\nThese questions help turn the trail into a reference manual, not just a reading sequence. At different stages of the career, the same article can hit differently. The beginner sees one layer. The junior sees another. The mid-level developer sees another. The senior comes back and notices that well executed fundamentals still support everything.`,
      },
    },
    {
      title: { pt: 'Como conectar com o próximo artigo', en: 'How to connect with the next article' },
      content: {
        pt: `Não leia a trilha como uma pilha de páginas soltas. Leia como uma conversa longa. Um artigo prepara o terreno para outro. Às vezes o próximo aprofunda uma habilidade técnica. Às vezes muda para carreira. Às vezes parece distante, mas mostra o outro lado da mesma responsabilidade.\n\nDepois de terminar ${titlePt}, anote uma dúvida que ficou aberta. Essa dúvida é importante. Ela mostra onde seu repertório ainda precisa crescer. Quando entrar no próximo artigo, tente procurar resposta para essa dúvida ou pelo menos uma forma melhor de formulá-la.\n\nA evolução em tecnologia raramente acontece como uma linha reta. Você aprende um conceito, aplica mal, volta, entende melhor, encontra outro problema, muda a pergunta e continua. A trilha foi pensada para acompanhar esse movimento. Não para dar a sensação de que tudo termina em uma leitura.`,
        en: `Do not read the trail as a pile of disconnected pages. Read it as a long conversation. One article prepares the ground for another. Sometimes the next one deepens a technical skill. Sometimes it moves to career. Sometimes it looks distant, but shows the other side of the same responsibility.\n\nAfter finishing ${titleEn}, write down one doubt that remains open. That doubt matters. It shows where your repertoire still needs to grow. When you enter the next article, try to find an answer to that doubt or at least a better way to phrase it.\n\nGrowth in technology rarely happens in a straight line. You learn a concept, apply it poorly, come back, understand it better, find another problem, change the question and continue. The trail was designed to follow that movement. Not to create the illusion that everything ends in one reading.`,
      },
    },
  ];
};

export const enhanceManualArticle = (article: MarketTrailArticle): MarketTrailArticle => {
  if (!article.id.startsWith('mt-') || hasManualLayer(article)) return article;

  const minutes = minutesFromReadTime(article.readTime) + 78;

  return {
    ...article,
    readTime: `${minutes} min`,
    sections: [...article.sections, ...buildManualSections(article)],
  };
};
